// Standard FNV-1a implementation
const FNV_OFFSET_BASIS = 0x811c9dc5;
const FNV_PRIME = 0x01000193;  // 16777619

function fnv1a(data) {
  let hash = FNV_OFFSET_BASIS;
  for (let i = 0; i < data.length; i++) {
    hash = (hash ^ data[i]) >>> 0;
    hash = (hash * FNV_PRIME) >>> 0;
  }
  return hash;
}

const fs = require('fs');
const aFile = fs.readFileSync('data/files/a.txt');
const bFile = fs.readFileSync('data/files/b.txt');

const hashA = fnv1a(aFile);
const hashB = fnv1a(bFile);

console.log('a.txt hash:', hashA.toString(16).padStart(8, '0'));
console.log('b.txt hash:', hashB.toString(16).padStart(8, '0'));
console.log('Expected a.txt: e37d9473');
console.log('Expected b.txt: 784f5257');
"
","description":"Test different FNV-1a implementation"}

