const PRIME = 16777619;

function fnv1aVari(bytes) {
  let hash = OFFSET;
  for (let i = 0; i < bytes.length; i++) {
    hash ^= bytes[i];
    hash = (hash * PRIME) >>> 0;
  }
  // Try different final conversions
